var t=`0654-nigerian-jollof-rice`;var n=`world-0654`;var o=`NG`;var r=`western-africa`;var a=4;var s=68;var l={en:`Nigerian Jollof Rice`,ua:`Рис джолоф по-нігерійськи`};var d={en:`Nigerian Jollof Rice is a Nigeria classic prepared with yellow onion, red bell pepper, scotch bonnet pepper, tomato. A measured home-style version, with ingredients assigned to the cooking steps where they are used.`,ua:`Рис джолоф по-нігерійськи, страва кухні країни Нігерія зі складниками: жовта цибуля, червоний солодкий перець, перець скотч-боннет, помідор. Домашній рецепт із кількостями, прив’язаними до відповідних етапів приготування.`};var c=[{en:`Chop the vegetables as needed. Sauté the listed ingredients over medium heat, stirring, for about 12 minutes until softened and aromatic.`,ua:`Наріжте овочі за потреби. Пасеруйте зазначені складники на середньому вогні, помішуючи, приблизно 12 хвилин до м’якості й аромату.`,t:[`chopping`,`sauteing`],m:12,i:[[`yellow-onion`,200,`g`],[`red-bell-pepper`,260,`g`],[`scotch-bonnet-pepper`,1,`pcs`],[`sunflower-oil`,55,`ml`]]},{en:`Simmer the liquid and flavorings uncovered for about 15 minutes until reduced and concentrated.`,ua:`Уварюйте рідину з приправами без кришки приблизно 15 хвилин до насичення та загустіння.`,t:[`reducing-sauce`],m:15,i:[[`tomato`,520,`g`],[`tomato-paste`,65,`g`],[`garlic`,4,`clove`],[`curry-powder`,6,`g`],[`dried-thyme`,4,`g`]]},{en:`Pour parboiled rice into the reduced pepper-tomato base with measured hot stock, cover and cook gently until the liquid absorbs.`,ua:`Всипте пропарений рис у виварену перцево-томатну основу, додайте виміряний гарячий бульйон, накрийте й варіть до поглинання рідини.`,t:[`rice-washing`,`absorption-cooking`],m:28,i:[[`parboiled-rice`,380,`g`],[`chicken-stock`,640,`ml`],[`bay-leaf`,2,`leaf`]]},{en:`Take off the heat and let the rice rest under a clean towel or lid for about 10 minutes before serving.`,ua:`Зніміть із вогню та дайте рису відпочити під чистим рушником або кришкою приблизно 10 хвилин перед подаванням.`,t:[`rice-resting`,`fluffing-grains`],m:10,i:[]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:3,i:[[`parsley`,18,`g`]]}];var g={slug:t,id:n,country:`NG`,region:r,servings:4,minutes:68,title:l,text:d,steps:c};export{o as country,g as default,n as id,s as minutes,r as region,a as servings,t as slug,c as steps,d as text,l as title};